const item = $input.first().json;

// Extract text from the OpenAI Responses API output (with fallbacks)
let aiResponse = '';
if (Array.isArray(item.output)) {
  for (const msg of item.output) {
    if (Array.isArray(msg.content)) {
      for (const c of msg.content) {
        if (c.type === 'output_text' && c.text) aiResponse += c.text;
      }
    }
  }
} else if (item.message && item.message.content) {
  aiResponse = item.message.content;
} else if (typeof item.text === 'string') {
  aiResponse = item.text;
}

let parsed;
try {
  const cleaned = aiResponse.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    tweet_thread: aiResponse,
    linkedin_post: '',
    instagram_caption: '',
    summary: '',
    hashtags: '',
    image_prompt: ''
  };
}

const input = $('Parse Input').first().json;

return [{
  json: {
    source_text: input.source_text,
    source_type: input.source_type || 'text',
    source_url: input.source_url || '',
    source_file_name: input.source_file_name || '',
    language: input.language,
    tone: input.tone,
    session_id: input.session_id,
    tweet_thread: parsed.tweet_thread || '',
    linkedin_post: parsed.linkedin_post || '',
    instagram_caption: parsed.instagram_caption || '',
    summary: parsed.summary || '',
    hashtags: parsed.hashtags || '',
    image_prompt: parsed.image_prompt || ''
  }
}];

const raw = $input.first().json;
const html = String(raw.data || raw.body || '');

// remove script/style/nav/header/footer blocks
let text = html
  .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<nav\b[^>]*>[\s\S]*?<\/nav>/gi, '')
  .replace(/<header\b[^>]*>[\s\S]*?<\/header>/gi, '')
  .replace(/<footer\b[^>]*>[\s\S]*?<\/footer>/gi, '');

// strip remaining tags + collapse whitespace
text = text.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

if (!text) {
  throw new Error('No readable text found at this URL (the page may be rendered by JavaScript).');
}

return [{
  json: {
    source_text: text.substring(0, 12000),
    source_type: 'url'
  }
}];

const base = $('Parse Output').first().json;
const img = $input.first().json || {};

let imageData = '';

// لو الصورة راجعة كـ binary
if (img.data && typeof img.data === 'string') {
  // لو الـ binary متحول لـ base64
  imageData = 'data:image/png;base64,' + img.data;
} else if (img.binary && img.binary.data) {
  // لو الـ binary في مكان تاني
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  imageData = 'data:image/png;base64,' + buffer.toString('base64');
}

return [{
  json: {
    ...base,
    image_url: imageData
  }
}];
